-- Parking conditions, P1 (docs/designs/2026-10-26-parking-conditions-and-fees.md
-- §1, §4, §5.1–§5.4; stack C, C2). Adds condition and zones_complete to both
-- spot tables, the checks valid_condition(), valid_zones() and
-- valid_spot_condition(), viewport v3, and the conservative projection the
-- original and v2 viewports give builds that cannot read conditions.
-- Every existing row gets condition null and zones_complete false, which is
-- legacy-safe: every RPC answers as before.
--
-- The two sections below are copied from supabase/contract/parking_contract.sql,
-- generated by tool/gen_contract_sql.py from parking_contract.json;
-- tool/test_gen_contract_sql.py checks that the latest migration defining
-- each of their functions matches the generator. Its fee v2 section belongs
-- to C3 and is not here: valid_fee() stays the live v1 check.

-- ===== 共用：parking_contract() 與輔助函式（C2、C3 都需要） =====
-- ===== 共用：parking_contract() 與輔助函式（C2、C3 都需要） =====
create or replace function public.parking_contract() returns jsonb
language sql immutable set search_path='' as $contract$
  select $json${"version":1,"space_types":["paidMotorcycle","freeMotorcycle","heavyOnly","car","offStreet","disabledMotorcycle","timedMotorcycle","flexShared","evMotorcycle"],"access_kinds":["scooterOnly","scooterHeavy","heavyCar","noMotorcycle","heavyOnly"],"placement":{"off_street_space_types":["offStreet"],"off_street_facility_types":["multiStorey","underground","surface"]},"time":{"pattern":"^([01][0-9]|2[0-3]):[0-5][0-9]$","days":["all","weekday","holiday"],"weekdays":["mon","tue","wed","thu","fri","sat","sun"],"optional_pair":["from","to"]},"date":{"pattern":"^(19|[2-9][0-9])[0-9]{2}-[0-9]{2}-[0-9]{2}$"},"condition":{"keys":["bay","use","share","charge","limits","schedule","basis"],"zone_keys":["allow"],"bay":["motorcycle","heavy","car"],"use":["usual","share"],"share":{"scooter_heavy":"motorcycle","car_motorcycle":"car"},"charge":["toll","free"],"limits":{"time_limit":{"required":[],"optional":{"max_minutes":{"min":1,"max":1440}}},"special_vehicle":{"required":["vehicle"],"optional":{}},"ev_only":{"required":[],"optional":{}}},"special_vehicles":["disabled_modified"],"street_charge_optional_with":["time_limit","special_vehicle","ev_only"],"allow_keys":["scooter","heavy"],"schedule":{"keys":["days","from","to","vehicles"],"max_entries":8,"vehicles":["scooter","heavy","car"]},"basis":{"keys":["source_url","evidence_id","effective_date","expires_on"],"required_one_of":["source_url","evidence_id"],"reserved":["evidence_id"],"source_url":{"pattern":"^https://\\S+$","max_length":2048,"length_unit":"utf16"}}},"zone":{"area":["motorcycle","car","heavy","mixed"]},"conversion":{"from_space_type":{"paidMotorcycle":{"bay":"motorcycle","use":"usual","charge":"toll"},"freeMotorcycle":{"bay":"motorcycle","use":"usual","charge":"free"},"heavyOnly":{"bay":"heavy","use":"usual"},"car":{"bay":"car","use":"usual"},"offStreet":null,"disabledMotorcycle":{"bay":"motorcycle","limits":[{"kind":"special_vehicle","vehicle":"disabled_modified"}]},"timedMotorcycle":{"bay":"motorcycle","use":"usual","limits":[{"kind":"time_limit"}]},"flexShared":{"bay":"car","use":"share","share":"car_motorcycle"},"evMotorcycle":{"bay":"motorcycle","limits":[{"kind":"ev_only"}]}},"from_access":{"scooterOnly":{"bay":"motorcycle","use":"usual","allow":{"scooter":true,"heavy":false}},"scooterHeavy":{"bay":"motorcycle","use":"share","share":"scooter_heavy","allow":{"scooter":true,"heavy":true}},"heavyCar":{"bay":"car","use":"usual","allow":{"scooter":false,"heavy":true}},"heavyOnly":{"bay":"heavy","use":"usual","allow":{"scooter":false,"heavy":true}},"noMotorcycle":{"allow":{"scooter":false,"heavy":false}}},"to_space_type":[{"when":{"placement":"off_street"},"space_type":"offStreet"},{"when":{"limit":"special_vehicle"},"space_type":"disabledMotorcycle"},{"when":{"limit":"ev_only"},"space_type":"evMotorcycle"},{"when":{"share":"car_motorcycle"},"space_type":"flexShared"},{"when":{"limit":"time_limit"},"space_type":"timedMotorcycle"},{"when":{"bay":"heavy"},"space_type":"heavyOnly"},{"when":{"bay":"car"},"space_type":"car"},{"when":{"bay":"motorcycle","charge":"toll"},"space_type":"paidMotorcycle"},{"when":{"bay":"motorcycle","charge":"free"},"space_type":"freeMotorcycle"}],"to_access":"allow 與 from_access 的 allow 相同，且 from_access 有 bay 時 bay 也相同","legacy_safe":{"unsafe_keys":["schedule"],"unsafe_basis_keys":["expires_on"],"lossy_share":"scooter_heavy","lossy_limit_keys":["max_minutes"],"assumed_charge":{"timedMotorcycle":"toll"},"lossy_when_unconfirmed":["bay","use","share","charge"]}},"fee":{"max_bytes":4096,"vehicles":["scooter","heavy","car"],"follow":{"vehicles":["heavy"],"modes":["same_as_scooter","same_as_car"],"optional":{"factor_pct":{"min":100,"max":1000}}},"modes":{"free":{"required":{},"optional":{}},"posted":{"required":{},"optional":{}},"hourly":{"required":{"amount":{"min":0,"max":10000},"per_minutes":{"min":1,"max":1440}},"optional":{"unit_minutes":{"min":1,"max":"per_minutes"},"free_minutes":{"min":1,"max":1440},"daily_cap":{"min":0,"max":10000},"cap_reset":"cap_reset"}},"per_visit":{"required":{"amount":{"min":0,"max":10000}},"optional":{"max_minutes":{"min":1,"max":1440},"renew":"renew","extension":"extension"}},"daily":{"required":{"amount":{"min":0,"max":10000}},"optional":{"cap_reset":"cap_reset"}},"by_time":{"required":{"periods":"periods"},"optional":{"cross_period":"cross_period"}}},"enums":{"cap_reset":["calendar_day","rolling_24h","per_entry"],"renew":["none","midnight"],"cross_period":["each_period","entry_only"]},"extension":{"required":{"amount":{"min":0,"max":10000},"max_times":{"min":1,"max":10}},"optional":{"minutes":{"min":1,"max":1440}}},"periods":{"max_entries":6,"keys":["days","from","to","rate"],"nested_modes":["free","posted","hourly","per_visit","daily"]}}}$json$::jsonb;
$contract$;

-- A whole number in range; CASE so a string returns false, not a cast error.
create or replace function public.contract_whole(p jsonb,p_min numeric,p_max numeric) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='number'
    then (p::text)::numeric=trunc((p::text)::numeric) and (p::text)::numeric between p_min and p_max
    else false end;
$$;

create or replace function public.contract_str_in(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string' and p_list ? (p#>>'{}'),false);
$$;

-- A non-empty array of distinct strings drawn from p_list.
create or replace function public.contract_subset(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then jsonb_array_length(p)>0
    and not exists(select 1 from jsonb_array_elements(p) e where not public.contract_str_in(e,p_list))
    and (select count(distinct e) from jsonb_array_elements(p) e)=jsonb_array_length(p)
    else false end;
$$;

create or replace function public.contract_date(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string'
    and (p#>>'{}') ~ (public.parking_contract()->'date'->>'pattern')
    and pg_input_is_valid(p#>>'{}','date'),false);
$$;

-- days, from and to of a schedule slot or a fee period; leaving out both
-- from and to means all day.
create or replace function public.contract_slot_times(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(case when jsonb_typeof(p->'days')='string'
      then public.contract_str_in(p->'days',public.parking_contract()->'time'->'days')
      else public.contract_subset(p->'days',public.parking_contract()->'time'->'weekdays') end
    and (not p ?| array(select jsonb_array_elements_text(public.parking_contract()->'time'->'optional_pair'))
    or jsonb_typeof(p->'from')='string' and jsonb_typeof(p->'to')='string'
    and (p->>'from') ~ (public.parking_contract()->'time'->>'pattern')
    and (p->>'to') ~ (public.parking_contract()->'time'->>'pattern')
    and p->>'from'<>p->>'to'),false);
$$;

-- An object with only the listed keys, and all of them except the optional
-- from/to pair, which contract_slot_times checks.
create or replace function public.contract_slot_keys(p jsonb,p_keys jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='object' then
    not exists(select 1 from jsonb_object_keys(p) k where not p_keys ? k)
    and not exists(select 1 from jsonb_array_elements_text(p_keys) k
      where not p ? k and not public.parking_contract()->'time'->'optional_pair' ? k)
    else false end;
$$;

-- ===== 停放條件：valid_condition()、condition_space_type()（C2 複製本段與共用段） =====

-- A bay's or a zone's condition (§1.2, §4.3), the same rules as
-- validCondition in validate.ts and lib/models/parking_condition.dart.
create or replace function public.valid_condition(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  p jsonb:=p_condition;
  c jsonb:=public.parking_contract()->'condition';
  l jsonb; v jsonb; spec jsonb; f record; kinds text[]:='{}';
begin
  if jsonb_typeof(p) is distinct from 'object' or p='{}'::jsonb then return false; end if;
  if exists(select 1 from jsonb_object_keys(p) k
      where not (c->'keys' ? k or (p_zone and c->'zone_keys' ? k))) then return false; end if;
  if (p ? 'bay' and not public.contract_str_in(p->'bay',c->'bay'))
    or (p ? 'use' and not public.contract_str_in(p->'use',c->'use'))
    or (p ? 'share' and not (jsonb_typeof(p->'share')='string' and c->'share' ? (p->>'share')))
    or (p ? 'charge' and not public.contract_str_in(p->'charge',c->'charge')) then return false; end if;
  if not p_zone and not p ? 'bay' then return false; end if;
  if (p ? 'share')<>coalesce(p->>'use'='share',false) then return false; end if;
  if p ? 'share' and (p->>'bay') is distinct from (c->'share'->>(p->>'share')) then return false; end if;

  if p ? 'limits' then
    if jsonb_typeof(p->'limits') is distinct from 'array'
      or jsonb_array_length(p->'limits') not between 1 and (select count(*) from jsonb_object_keys(c->'limits'))
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'limits') e loop
      if jsonb_typeof(l) is distinct from 'object' or jsonb_typeof(l->'kind') is distinct from 'string'
        or not c->'limits' ? (l->>'kind') or (l->>'kind')=any(kinds) then return false; end if;
      kinds:=kinds||(l->>'kind');
      spec:=c->'limits'->(l->>'kind');
      for f in select key,value from jsonb_each(l) loop
        continue when f.key='kind' or spec->'required' ? f.key;
        if not spec->'optional' ? f.key or not public.contract_whole(f.value,
            (spec->'optional'->f.key->>'min')::numeric,(spec->'optional'->f.key->>'max')::numeric)
        then return false; end if;
      end loop;
      if exists(select 1 from jsonb_array_elements_text(spec->'required') r where not l ? r) then return false; end if;
      if l ? 'vehicle' and not public.contract_str_in(l->'vehicle',c->'special_vehicles') then return false; end if;
    end loop;
  end if;
  if not p_zone and p->>'bay'='motorcycle' and not p ? 'charge'
    and not kinds && array(select jsonb_array_elements_text(c->'street_charge_optional_with'))
  then return false; end if;

  if p ? 'allow' then
    v:=p->'allow';
    if jsonb_typeof(v) is distinct from 'object' or v='{}'::jsonb
      or exists(select 1 from jsonb_each(v) e where not c->'allow_keys' ? e.key or jsonb_typeof(e.value)<>'boolean')
    then return false; end if;
    if v->'scooter'='true'::jsonb and p->>'bay'='heavy' then return false; end if;
  end if;

  if p ? 'schedule' then
    if jsonb_typeof(p->'schedule') is distinct from 'array'
      or jsonb_array_length(p->'schedule') not between 1 and (c->'schedule'->>'max_entries')::integer
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'schedule') e loop
      if not public.contract_slot_keys(l,c->'schedule'->'keys') or not public.contract_slot_times(l)
        or not public.contract_subset(l->'vehicles',c->'schedule'->'vehicles') then return false; end if;
    end loop;
  end if;

  if p ? 'basis' then
    v:=p->'basis';
    if jsonb_typeof(v) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(v) k where not c->'basis'->'keys' ? k) then return false; end if;
    -- Reserved until photo evidence ships (verification plan P2).
    if exists(select 1 from jsonb_array_elements_text(c->'basis'->'reserved') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if not exists(select 1 from jsonb_array_elements_text(c->'basis'->'required_one_of') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if v ? 'source_url' and not coalesce(jsonb_typeof(v->'source_url')='string'
        -- UTF-16 code units, as Dart and JS count: characters outside the BMP count twice.
        and char_length(v->>'source_url')+regexp_count(v->>'source_url','[\U00010000-\U0010FFFF]')
          <=(c->'basis'->'source_url'->>'max_length')::integer
        and (v->>'source_url') ~ (c->'basis'->'source_url'->>'pattern'),false) then return false; end if;
    if (coalesce(jsonb_typeof(v->'effective_date'),'null')<>'null' and not public.contract_date(v->'effective_date'))
      or (coalesce(jsonb_typeof(v->'expires_on'),'null')<>'null' and not public.contract_date(v->'expires_on'))
    then return false; end if;
    if jsonb_typeof(v->'effective_date')='string' and jsonb_typeof(v->'expires_on')='string'
      and (v->>'expires_on') collate "C"<=(v->>'effective_date') collate "C" then return false; end if;
  end if;
  return true;
end;
$$;

-- The legacy space_type a condition is stored under (§1.3): the first
-- to_space_type rule that matches, or null.
create or replace function public.condition_space_type(p_condition jsonb,p_off_street boolean) returns text
language plpgsql immutable set search_path='' as $$
declare p jsonb:=p_condition; r jsonb; w jsonb;
begin
  for r in select e from jsonb_array_elements(public.parking_contract()->'conversion'->'to_space_type') e loop
    w:=r->'when';
    if (not w ? 'placement' or p_off_street)
      and (not w ? 'limit' or exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p->'limits')='array' then p->'limits' else '[]'::jsonb end) l
        where l->>'kind'=w->>'limit'))
      and (not w ? 'share' or p->>'share' is not distinct from w->>'share')
      and (not w ? 'bay' or p->>'bay' is not distinct from w->>'bay')
      and (not w ? 'charge' or p->>'charge' is not distinct from w->>'charge')
    then return r->>'space_type'; end if;
  end loop;
  return null;
end;
$$;

-- Whether a spot is off the street (§1.1 placement); never stored.
create or replace function public.condition_off_street(p_space_type text,p_facility_type text) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(public.parking_contract()->'placement'->'off_street_space_types' ? p_space_type,false)
    or coalesce(public.parking_contract()->'placement'->'off_street_facility_types' ? p_facility_type,false);
$$;

-- The legacy access a zone condition is written back as (§1.3, to_access):
-- the from_access entry with the same allow and, when the entry names a bay,
-- the same bay; null when none matches. At most one entry can match.
create or replace function public.condition_legacy_access(p_condition jsonb) returns text
language sql immutable set search_path='' as $$
  select min(a.key) from jsonb_each(public.parking_contract()->'conversion'->'from_access') a
  where jsonb_typeof(p_condition->'allow')='object'
    and (a.value->'allow'->'scooter') is not distinct from (p_condition->'allow'->'scooter')
    and (a.value->'allow'->'heavy') is not distinct from (p_condition->'allow'->'heavy')
    and (not a.value ? 'bay' or (a.value->'bay') is not distinct from (p_condition->'bay'));
$$;

-- legacySafe (§1.3, conversion.legacy_safe): whether old apps, reading only
-- the legacy space_type (a street condition) or access (p_zone), see the
-- same condition or a more conservative one. Converts and reads back, then
-- compares, losing only (a) scooter_heavy read back as usual, (b) a basis
-- without the unsafe keys, (c) the lossy limit keys and (d) facets the read
-- back leaves unconfirmed, except a charge old apps assume. Null is safe.
create or replace function public.condition_legacy_safe(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  conv jsonb:=public.parking_contract()->'conversion';
  r jsonb:=conv->'legacy_safe';
  o jsonb:=p_condition; b jsonb; t text; k text;
  lossy text[]:=array(select jsonb_array_elements_text(r->'lossy_limit_keys'));
begin
  if o is null or jsonb_typeof(o)='null' then return true; end if;
  if p_zone then
    t:=public.condition_legacy_access(o);
    b:=conv->'from_access'->t;
  else
    t:=public.condition_space_type(o,false);
    b:=conv->'from_space_type'->t;
  end if;
  if b is null or jsonb_typeof(b)<>'object' then return false; end if;
  if o ?| array(select jsonb_array_elements_text(r->'unsafe_keys')) then return false; end if;
  -- (b) a basis without the unsafe keys; a null value counts as left out.
  if exists(select 1 from jsonb_array_elements_text(r->'unsafe_basis_keys') x
      where coalesce(jsonb_typeof(o->'basis'->x),'null')<>'null') then return false; end if;
  o:=o-'basis'; b:=b-'basis';
  -- (c) limit keys old apps never read.
  if jsonb_typeof(o->'limits')='array' then
    o:=jsonb_set(o,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(o->'limits') e));
  end if;
  if jsonb_typeof(b->'limits')='array' then
    b:=jsonb_set(b,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(b->'limits') e));
  end if;
  -- (a) a shared use read back as usual.
  if o->>'share'=r->>'lossy_share' and b->>'use'='usual' and not b ? 'share' then
    o:=(o-'share')||'{"use":"usual"}'::jsonb;
  end if;
  -- (d) facets the legacy value leaves unconfirmed, except an assumed charge.
  if not p_zone and r->'assumed_charge' ? t and not b ? 'charge' and o ? 'charge'
    and o->>'charge'<>r->'assumed_charge'->>t then return false; end if;
  for k in select jsonb_array_elements_text(r->'lossy_when_unconfirmed') loop
    if not b ? k then o:=o-k; end if;
  end loop;
  return o=b;
end;
$$;

-- Whether old builds, which read a zone's access only, read a stored zone
-- (an element of parking_zones) as it is: it has no condition, or a
-- legacy-safe one stored with the access it writes back.
create or replace function public.zone_legacy_safe(p_zone jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p_zone->'condition'),'null')='null'
    or (public.condition_legacy_safe(p_zone->'condition',true)
      and (p_zone->>'access') is not distinct from public.condition_legacy_access(p_zone->'condition'));
$$;

-- Whether a whole spot is legacy-safe: a street spot by its condition, a lot
-- only without a top-level condition and when every zone is.
create or replace function public.condition_legacy_safe_spot(p_off_street boolean,p_condition jsonb,p_zones jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when p_off_street then coalesce(jsonb_typeof(p_condition),'null')='null'
      and not exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p_zones)='array' then p_zones else '[]'::jsonb end) z
        where not public.zone_legacy_safe(z))
    else public.condition_legacy_safe(p_condition,false) end;
$$;

-- ===== 欄位與檢查 =====

-- condition: the bay's parking condition (§1.2), on street spots only; a
-- lot keeps its bays in parking_zones[].condition. zones_complete: the
-- zones cover the whole lot, set only by administrators and imports.
-- Every existing row gets null and false, which reads as it does today.
alter table public.community_spots
  add column condition jsonb,
  add column zones_complete boolean not null default false;
alter table public.official_heavy_spots
  add column condition jsonb,
  add column zones_complete boolean not null default false;

-- A lot's zones (§1.1, §1.3): the fee contract of valid_zone_fees(), plus an
-- optional area and condition. Old builds read only access; a zone whose
-- access is not the one its condition writes back is not legacy-safe
-- (zone_legacy_safe()), so they get it without its access.
create function public.valid_zones(p_zones jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p_zones) is distinct from 'array' then false else
    not exists(select 1 from jsonb_array_elements(p_zones) z
      where jsonb_typeof(z) is distinct from 'object'
        or (z ? 'fee' and not public.valid_fee(z->'fee'))
        or (z ? 'area' and not public.contract_str_in(z->'area',public.parking_contract()->'zone'->'area'))
        or (z ? 'condition' and not public.valid_condition(z->'condition',true))) end;
$$;

-- The spot-level combinations no data may hold (§4.3, DB rows): a lot has
-- no top-level condition; a street spot has no zones and no zones_complete,
-- and its condition is valid and decides its space_type.
create function public.valid_spot_condition(p_space_type text,p_facility_type text,p_condition jsonb,
  p_zones jsonb,p_zones_complete boolean) returns boolean
language sql immutable set search_path='' as $$
  select case when public.condition_off_street(p_space_type,p_facility_type) then p_condition is null
    else not coalesce(p_zones_complete,false)
      and coalesce(jsonb_array_length(p_zones),0)=0
      and (p_condition is null or (public.valid_condition(p_condition,false)
        and public.condition_space_type(p_condition,false) is not distinct from p_space_type)) end;
$$;

-- valid_zones() checks everything valid_zone_fees() did, so it takes its
-- place. Added not valid, then validated, as city_rules_restriction_required.
alter table public.community_spots drop constraint community_spots_zone_fees_check;
alter table public.community_spots add constraint community_spots_zones_check
  check (public.valid_zones(parking_zones)) not valid;
alter table public.community_spots validate constraint community_spots_zones_check;
alter table public.community_spots add constraint community_spots_condition_check
  check (public.valid_spot_condition(space_type,facility_type,condition,parking_zones,zones_complete)) not valid;
alter table public.community_spots validate constraint community_spots_condition_check;
alter table public.official_heavy_spots drop constraint official_spots_zone_fees_check;
alter table public.official_heavy_spots add constraint official_spots_zones_check
  check (public.valid_zones(parking_zones)) not valid;
alter table public.official_heavy_spots validate constraint official_spots_zones_check;
alter table public.official_heavy_spots add constraint official_spots_condition_check
  check (public.valid_spot_condition(space_type,facility_type,condition,parking_zones,zones_complete)) not valid;
alter table public.official_heavy_spots validate constraint official_spots_condition_check;

-- ===== 讀取：public_spots、viewport v3 與舊版的保守投影（§5.2） =====

grant select (condition,zones_complete) on public.community_spots to anon,authenticated;
-- 202610250080_admin_verified_eligibility.sql's view plus the two columns.
-- The community viewport RPCs return setof this view, so v2 and the
-- original carry them too; older builds ignore the extra keys.
create or replace view public.public_spots with (security_invoker=true) as
  select id,source,source_name,source_url,license_note,name,lat,lng,city,district,space_type,fee_note,note,
    scooter_total,available,scooter_allowed,heavy_allowed,status,updated_at,last_confirmed_at,created_at,
    facility_type,parking_access,address,road_segment,entrance_note,parking_guide,special_rules,
    photo_urls,parking_zones,fee,contributor_name,contributor_role,scooter_verified_at,heavy_verified_at,
    condition,zones_complete
  from public.community_spots;

-- What builds that cannot read condition must see instead of p_row (a spot
-- row as jsonb), as the fields to override; '{}' when the spot is
-- legacy-safe (§1.3). Otherwise those builds would read a schedule, an
-- expiry or a free timed bay more loosely than it is, so the spot becomes an
-- unverified lot: space_type offStreet, both vehicle flags null, status
-- pending where the row has one (community spots), no condition, and each
-- zone that is not legacy-safe without its access. Those builds judge it 待確認 for every
-- vehicle, as favorites' `exact` does. The original and _v2 viewports both
-- use it; the app's favorites write the same projection (ParkingSpot.toJson).
create function public.legacy_projection(p_row jsonb) returns jsonb
language sql immutable set search_path='' as $$
  select case when public.condition_legacy_safe_spot(
      public.condition_off_street(p_row->>'space_type',p_row->>'facility_type'),
      p_row->'condition',p_row->'parking_zones')
    then '{}'::jsonb
    else jsonb_build_object('space_type','offStreet','scooter_allowed',null,'heavy_allowed',null,'condition',null,
      'parking_zones',coalesce((select jsonb_agg(case when public.zone_legacy_safe(z)
          then z else z-'access' end order by n)
        from jsonb_array_elements(case when jsonb_typeof(p_row->'parking_zones')='array'
          then p_row->'parking_zones' else '[]'::jsonb end) with ordinality e(z,n)),'[]'::jsonb))
      ||case when p_row ? 'status' then '{"status":"pending"}'::jsonb else '{}'::jsonb end end;
$$;

-- Builds that read condition: every row and column as stored.
create function public.viewport_spots_v3(south double precision,west double precision,north double precision,east double precision)
returns setof public.public_spots language sql stable security invoker
set search_path=public,extensions as $$
  select p.* from public.community_spots s join public.public_spots p on p.id=s.id
  where $1 >= -90 and $3 <= 90 and $2 >= -180 and $4 <= 180
    and $3 > $1 and $4 > $2 and $3-$1 <= 0.5 and $4-$2 <= 0.5
    and s.location operator(extensions.&&)
      extensions.st_makeenvelope($2,$1,$4,$3,4326)::extensions.geography
    and s.lat between $1 and $3 and s.lng between $2 and $4
  order by p.id
  limit 501;
$$;
grant execute on function public.viewport_spots_v3(double precision,double precision,double precision,double precision) to anon,authenticated;

-- 202610240002_space_types.sql's two functions, each row through
-- legacy_projection().
create or replace function public.viewport_spots_v2(south double precision,west double precision,north double precision,east double precision)
returns setof public.public_spots language sql stable security invoker
set search_path=public,extensions as $$
  select r.* from public.community_spots s join public.public_spots p on p.id=s.id
    cross join lateral jsonb_populate_record(p,public.legacy_projection(to_jsonb(p))) r
  where $1 >= -90 and $3 <= 90 and $2 >= -180 and $4 <= 180
    and $3 > $1 and $4 > $2 and $3-$1 <= 0.5 and $4-$2 <= 0.5
    and s.location operator(extensions.&&)
      extensions.st_makeenvelope($2,$1,$4,$3,4326)::extensions.geography
    and s.lat between $1 and $3 and s.lng between $2 and $4
  order by p.id
  limit 501;
$$;
-- Still only the original five kinds as stored; a row it keeps may then be
-- projected (a heavyOnly bay with a schedule, say).
create or replace function public.viewport_spots(south double precision,west double precision,north double precision,east double precision)
returns setof public.public_spots language sql stable security invoker
set search_path=public,extensions as $$
  select r.* from public.community_spots s join public.public_spots p on p.id=s.id
    cross join lateral jsonb_populate_record(p,public.legacy_projection(to_jsonb(p))) r
  where $1 >= -90 and $3 <= 90 and $2 >= -180 and $4 <= 180
    and $3 > $1 and $4 > $2 and $3-$1 <= 0.5 and $4-$2 <= 0.5
    and s.location operator(extensions.&&)
      extensions.st_makeenvelope($2,$1,$4,$3,4326)::extensions.geography
    and s.lat between $1 and $3 and s.lng between $2 and $4
    and s.space_type in ('paidMotorcycle','freeMotorcycle','heavyOnly','car','offStreet')
  order by p.id
  limit 501;
$$;

-- 202610250050_contributor_attribution.sql's official functions. v2 and the
-- original keep their shape and project unsafe rows (official rows have no
-- status, so only the flags drop); v3 adds condition and zones_complete.
create function public.official_viewport_spots_v3(south double precision,west double precision,north double precision,east double precision)
returns table(
  id text,source text,source_url text,source_name text,license_note text,name text,lat double precision,lng double precision,
  city text,district text,space_type text,fee_note text,note text,
  heavy_allowed boolean,scooter_allowed boolean,status text,updated_at timestamptz,
  facility_type text,parking_access text,address text,road_segment text,scooter_total integer,
  entrance_note text,parking_guide text,special_rules text,photo_urls jsonb,parking_zones jsonb,fee jsonb,
  contributor_name text,contributor_role text,condition jsonb,zones_complete boolean
) language sql stable security invoker set search_path=public as $$
  select 'official:'||o.id,'official',o.source_url,o.source_name,o.license_note,o.name,o.lat,o.lng,
    o.city,o.district,o.space_type,o.fee_note,o.note,
    o.heavy_allowed,o.scooter_allowed,'confirmed',o.updated_at,
    o.facility_type,o.parking_access,o.address,o.road_segment,o.scooter_total,
    o.entrance_note,o.parking_guide,o.special_rules,o.photo_urls,o.parking_zones,o.fee,
    ''::text,'admin'::text,o.condition,o.zones_complete
  from public.official_heavy_spots o
  where $1 >= -90 and $3 <= 90 and $2 >= -180 and $4 <= 180
    and $3 > $1 and $4 > $2 and $3-$1 <= 0.5 and $4-$2 <= 0.5
    and o.lat between $1 and $3 and o.lng between $2 and $4
    and o.effective_date <= current_date
  order by o.id limit 501;
$$;
grant execute on function public.official_viewport_spots_v3(double precision,double precision,double precision,double precision) to anon,authenticated;

create or replace function public.official_viewport_spots_v2(south double precision,west double precision,north double precision,east double precision)
returns table(
  id text,source text,source_url text,source_name text,license_note text,name text,lat double precision,lng double precision,
  city text,district text,space_type text,fee_note text,note text,
  heavy_allowed boolean,scooter_allowed boolean,status text,updated_at timestamptz,
